/* 알림 발송 이력 등록 */
INSERT INTO NOTI_SNDNG_LOG
     ( MBR_SN
     , SCHDL_SN
     , NOTI_TYPE_CD
     , NOTI_CHNL_CD
     , SNDNG_RSLT_CD
     , BFHD_NOTI_CD
     , RTRY_NMTM
     , SCHDL_YMD
     , SNDNG_DT
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{mbrSn}
     , #{schdlSn}
     , #{notiTypeCd}
     , #{notiChnlCd}
     , #{sndngRsltCd}
     , #{bfhdNotiCd}
     , #{rtryNmtm}
     , #{schdlYmd}
     , NOW()
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

